// Some portions generated by Claude
import { useState, type CSSProperties } from "react";
import type { EndpointFacetValue, FilterFacet } from "./explorer-types.ts";
import { formatRangeValue } from "./facet-queries.ts";
import { facetValuesShown, NO_MATCH_VALUE } from "./graph-facets.ts";
import { Icon } from "./icons.tsx";
import type { FacetFilters } from "./use-facet-filters.ts";

/** Values a filter lists before "Show more". */
const FACET_VALUE_LIMIT = 12;

export type FilterPanelProps = {
  filters: FacetFilters;
  matchCount: number;
  nodeCount: number;
  typesLoading: boolean;
  /** Whether a load reached its LIMIT, so counting values in the whole repository can add something. */
  offerRepositoryCounts: boolean;
  onCountInRepository: (facet: FilterFacet) => Promise<EndpointFacetValue[] | null>;
  onClearAll: () => void;
  onClose: () => void;
};

/** The Filters panel: active filters as chips, a search over filters and values, and one disclosure per filter. */
export function FilterPanel({
  filters,
  matchCount,
  nodeCount,
  typesLoading,
  offerRepositoryCounts,
  onCountInRepository,
  onClearAll,
  onClose,
}: FilterPanelProps) {
  // How many values each filter lists; on a large graph a filter can have tens of thousands of them.
  const [valueLimits, setValueLimits] = useState<Map<string, number>>(() => new Map());
  const shownValues = (facet: FilterFacet, selected: ReadonlySet<string>) =>
    facetValuesShown(facet.values, selected, valueLimits.get(facet.id) ?? FACET_VALUE_LIMIT, filters.search);
  return (
    <aside
      id="graph-filter-sidebar"
      className="filter-sidebar"
      aria-label="Filter graph nodes by metadata and predicate values"
      onClick={(event) => event.stopPropagation()}
    >
      <div className="filter-sidebar-header">
        <div>
          <h3>Filters</h3>
          {filters.hasActive ? (
            <small>
              {matchCount} of {nodeCount} nodes match
            </small>
          ) : null}
        </div>
        {filters.hasActive ? (
          <button
            className="workbench-action workbench-action--ghost"
            type="button"
            onClick={onClearAll}
          >
            Clear all
          </button>
        ) : null}
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close graph filters"
          title="Close graph filters"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </div>
      {filters.chips.length ? (
        <ul className="filter-chips" aria-label="Active filters">
          {filters.chips.map((chip) => (
            <li key={`${chip.facetId} ${chip.valueId ?? "range"}`}>
              <button
                type="button"
                aria-label={`Remove ${chip.text}`}
                title="Remove this filter"
                onClick={() => filters.removeValue(chip.facetId, chip.valueId)}
              >
                <span>{chip.text}</span>
                <Icon name="close" />
              </button>
            </li>
          ))}
        </ul>
      ) : null}
      <label className="facet-search">
        <span className="workbench-visually-hidden">Search filters</span>
        <input
          type="search"
          value={filters.search}
          onChange={(event) => filters.setSearch(event.target.value)}
          placeholder="Search filters and values"
        />
      </label>
      <div className="filter-facets">
        {filters.listed.map((facet) => {
          const selectedValues = filters.selection.get(facet.id) ?? new Set<string>();
          const draft = selectedValues.size ? filters.rangeDrafts.get(facet.id) : undefined;
          const open =
            filters.facetOpen.get(facet.id) ??
            (facet.category === "type" || facet.category === "kind" || selectedValues.size > 0 || facet.searchHit);
          const preview = facet.range
            ? `${formatRangeValue(facet.range.kind, facet.range.min)} – ${formatRangeValue(facet.range.kind, facet.range.max)}`
            : facet.values.slice(0, 3).map((value) => value.label).join(", ") + (facet.values.length > 3 ? ", …" : "");
          return (
            <details
              className="filter-facet"
              key={facet.id}
              open={open}
              onToggle={(event) => {
                const isOpen = event.currentTarget.open;
                if (isOpen === open) return;
                filters.setFacetOpen((current) => new Map(current).set(facet.id, isOpen));
              }}
            >
              <summary>
                <span className="facet-chevron" aria-hidden="true" />
                <span className="facet-heading">
                  <strong>{facet.label}</strong>
                  {!open ? <small>{preview}</small> : null}
                </span>
                {selectedValues.size > 0 && (
                  <span className="facet-selected-count" aria-label="Active">
                    {facet.range ? "✓" : [...selectedValues].filter((value) => value !== NO_MATCH_VALUE).length}
                  </span>
                )}
              </summary>
              {facet.range ? (
                <div className="facet-range">
                  <input
                    type={facet.range.kind === "date" ? "date" : "number"}
                    step="any"
                    aria-label={`${facet.label} from`}
                    placeholder={formatRangeValue(facet.range.kind, facet.range.min)}
                    min={facet.range.kind === "date" ? formatRangeValue("date", facet.range.min) : undefined}
                    max={facet.range.kind === "date" ? formatRangeValue("date", facet.range.max) : undefined}
                    value={draft?.from ?? ""}
                    onChange={(event) => filters.updateRange(facet, "from", event.target.value)}
                  />
                  <span aria-hidden="true">–</span>
                  <input
                    type={facet.range.kind === "date" ? "date" : "number"}
                    step="any"
                    aria-label={`${facet.label} to`}
                    placeholder={formatRangeValue(facet.range.kind, facet.range.max)}
                    min={facet.range.kind === "date" ? formatRangeValue("date", facet.range.min) : undefined}
                    max={facet.range.kind === "date" ? formatRangeValue("date", facet.range.max) : undefined}
                    value={draft?.to ?? ""}
                    onChange={(event) => filters.updateRange(facet, "to", event.target.value)}
                  />
                </div>
              ) : open ? (
                <div className="facet-values">
                  {shownValues(facet, selectedValues).values.map((value) => {
                    const checked = selectedValues.has(value.id);
                    return (
                      <label
                        className={`facet-value${checked ? " is-selected" : ""}${value.count ? "" : " is-empty"}`}
                        key={value.id}
                        style={
                          {
                            "--facet-bar-width": `${Math.max(5, (value.count / facet.maxCount) * 100)}%`,
                            "--facet-color": value.visual.stroke,
                            "--facet-fill": value.visual.fill,
                          } as CSSProperties
                        }
                      >
                        <span className="facet-histogram" aria-hidden="true" />
                        <input
                          type="checkbox"
                          checked={checked}
                          aria-label={`${value.label}, ${value.count} ${value.count === 1 ? "node" : "nodes"}`}
                          onChange={(event) => filters.toggleValue(facet.id, value.id, event.target.checked)}
                        />
                        <span className="facet-swatch" aria-hidden="true" />
                        <span className="facet-value-label">{value.label}</span>
                        <small>{value.count}</small>
                      </label>
                    );
                  })}
                  {shownValues(facet, selectedValues).more ? (
                    <button
                      type="button"
                      className="filter-more"
                      onClick={() => setValueLimits((current) => new Map(current).set(facet.id, (current.get(facet.id) ?? FACET_VALUE_LIMIT) + 50))}
                    >
                      Show {Math.min(50, shownValues(facet, selectedValues).more).toLocaleString()} more of{" "}
                      {shownValues(facet, selectedValues).more.toLocaleString()}
                    </button>
                  ) : null}
                </div>
              ) : null}
              {facet.endpointQueryable && offerRepositoryCounts && !facet.range && !filters.repositoryCounts.has(facet.id) ? (
                <div className="facet-source">
                  <button
                    type="button"
                    title="The loads reached their limit, so these counts may be low. Count the loaded nodes' values in the whole repository."
                    disabled={filters.countingFacetId === facet.id}
                    onClick={() => void filters.countInRepository(facet, onCountInRepository)}
                  >
                    {filters.countingFacetId === facet.id ? "Counting…" : "Count in the whole repository"}
                  </button>
                </div>
              ) : null}
            </details>
          );
        })}
        {filters.listed.length < filters.displayed.length ? (
          <button className="filter-more" type="button" onClick={() => filters.setShowAll(true)}>
            {filters.displayed.length - filters.listed.length} more filters
          </button>
        ) : null}
        {!filters.displayed.length && !typesLoading && (
          <p className="filter-empty">
            {filters.search.trim() ? `Nothing matches “${filters.search.trim()}”.` : "Nothing to filter yet."}
          </p>
        )}
      </div>
    </aside>
  );
}
